54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    private final OwnerAuditor ownerAuditor;
68	
69	    private final IdempotencyStore idempotencyStore;
70	
71	    private final HttpServletRequest request;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper,
77	                                 OwnerAuditor ownerAuditor,
78	                                 IdempotencyStore idempotencyStore,
79	                                 HttpServletRequest request) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	        this.ownerAuditor = ownerAuditor;
85	        this.idempotencyStore = idempotencyStore;
86	        this.request = request;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        String idempotencyKey = this.request.getHeader("Idempotency-Key");
118	        ResponseEntity<OwnerDto> replay = replayCreatedOwner(idempotencyKey);
119	        if (replay != null) {
120	            return replay;
121	        }
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        if (this.clinicService.isRegistrationDateInFuture(owner.getRegistrationDate())) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setRegistrationDate(this.clinicService.resolveRegistrationDate(owner.getRegistrationDate()));
128	        if (this.clinicService.isDailyOwnerLimitReached(owner.getRegistrationDate())) {
129	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
130	        }
131	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        // Assign the deterministic householdId (derived from last name and postcode) so owners in
135	        // the same household share it automatically and it forms part of the identity key.
136	        this.clinicService.assignHousehold(owner);
137	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
138	        // Reject an exact duplicate: an owner whose whole identity key (normalized telephone,
139	        // email and householdId) already exists.
140	        if (this.clinicService.existsOwnerWithIdentityKey(owner)) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        owner.setNamesakeCount((int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        owner.setHouseholdSize((int) this.clinicService.countHouseholdMembers(owner));
145	        // Cap the membership level so a new household member never outranks its household by more
146	        // than one level above its current highest-ranked member.
147	        owner.setMembershipLevel(this.clinicService.resolveCappedMembershipLevel(owner));
148	        owner.setBulkSignupWarning(this.clinicService.isBulkSignupWarranted(owner.getRegistrationDate()));
149	        // Flag a soft match unless this is a declared household member (a declared member is not a
150	        // suspected duplicate): an existing owner sharing this owner's last name and postcode with a
151	        // different telephone.
152	        if (!declaredHouseholdMember) {
153	            Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
154	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
155	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
156	        }
157	        this.clinicService.saveOwner(owner);
158	        this.ownerAuditor.auditCreated(owner);
159	        this.idempotencyStore.record(idempotencyKey, owner.getId());
160	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
161	        headers.setLocation(UriComponentsBuilder.newInstance()
162	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
163	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
164	    }
165	
166	    /**
167	     * If {@code idempotencyKey} was already used to create an owner, return that original owner
168	     * with {@code 200 OK} so a repeated create replays the first result instead of creating a
169	     * duplicate. Returns {@code null} when there is nothing to replay (no key, or key unseen).
170	     */
171	    private ResponseEntity<OwnerDto> replayCreatedOwner(String idempotencyKey) {
172	        return this.idempotencyStore.find(idempotencyKey)
173	            .map(this.clinicService::findOwnerById)
174	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
175	            .orElse(null);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        currentOwner.setAddressLine1(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine1()));
186	        currentOwner.setAddressLine2(ownerMapper.normalizeAddress(ownerFieldsDto.getAddressLine2()));
187	        currentOwner.setAddress(ownerMapper.composeAddress(ownerFieldsDto));
188	        currentOwner.setCity(ownerFieldsDto.getCity());
189	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
190	        currentOwner.setLastName(ownerFieldsDto.getLastName());
191	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
192	        this.clinicService.saveOwner(currentOwner);
193	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Transactional
198	    @Override
199	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
200	        Owner owner = this.clinicService.findOwnerById(ownerId);
201	        if (owner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        this.clinicService.deleteOwner(owner);
205	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
211	        Owner owner = this.clinicService.findOwnerById(ownerId);
212	        if (owner == null) {
213	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	        }
215	        HttpHeaders headers = new HttpHeaders();
216	        Pet pet = petMapper.toPet(petFieldsDto);
217	        owner.setId(ownerId);
218	        pet.setOwner(owner);
219	        pet.getType().setName(null);
220	        this.clinicService.savePet(pet);
221	        PetDto petDto = petMapper.toPetDto(pet);
222	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
223	            .buildAndExpand(pet.getId()).toUri());
224	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Override
229	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
230	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
231	        if (currentOwner != null) {
232	            Pet currentPet = this.clinicService.findPetById(petId);
233	            if (currentPet != null) {
234	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
235	                currentPet.setName(petFieldsDto.getName());
236	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
237	                this.clinicService.savePet(currentPet);
238	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	
244	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
245	    @Override
246	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
247	        HttpHeaders headers = new HttpHeaders();
248	        Visit visit = visitMapper.toVisit(visitFieldsDto);
249	        Pet pet = new Pet();
250	        pet.setId(petId);
251	        visit.setPet(pet);
252	        this.clinicService.saveVisit(visit);
253	        VisitDto visitDto = visitMapper.toVisitDto(visit);
254	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
255	            .buildAndExpand(visit.getId()).toUri());
256	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
257	    }
258	
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
263	        Owner owner = this.clinicService.findOwnerById(ownerId);
264	        if (owner != null) {
265	            Pet pet = owner.getPet(petId);
266	            if (pet != null) {
267	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
268	            }
269	        }
270	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	    }
272	}
