261	    @Override
262	    @Transactional(readOnly = true)
263	    public boolean existsOwnerWithIdentityKey(Owner owner) throws DataAccessException {
264	        String identityKey = owner.getIdentityKey();
265	        // Owners can only share an identity key when they share a (normalized) telephone, so it is
266	        // enough to compare against the owners already stored with the same telephone. Soft-deleted
267	        // owners are ignored, so a duplicate is allowed once the only match has been deleted.
268	        return ownerRepository.findByTelephone(owner.getTelephone()).stream()
269	            .filter(existing -> !existing.isDeleted())
270	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
271	    }
272	
273	    /**
274	     * Find an existing owner that this (not yet persisted) owner soft-matches: one sharing its last
275	     * name (ignoring case) and postcode but carrying a different telephone, so it is not a hard
276	     * identity-key duplicate. Returns the matching owner's id (the lowest when several match), or
277	     * {@code null} when the owner has no postcode or nothing matches.
278	     */
279	    @Override
280	    @Transactional(readOnly = true)
281	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
282	        if (owner.getPostcode() == null) {
283	            return null;
284	        }
285	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
286	            .filter(existing -> !existing.isDeleted())
287	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
288	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
289	            .map(Owner::getId)
290	            .min(Integer::compareTo)
291	            .orElse(null);
292	    }
