294	    /**
295	     * The maximum number of owners allowed in a single city; once a city holds this many
296	     * owners it is considered at capacity and no further owners may be created there.
297	     */
298	    static final long CITY_CAPACITY = 50;
299	
300	    @Override
301	    @Transactional(readOnly = true)
302	    public boolean isCityAtCapacity(String city) throws DataAccessException {
303	        return ownerRepository.countByCityIgnoreCase(city) >= CITY_CAPACITY;
304	    }
305	
306	    /**
307	     * The maximum number of owners that may be created in a single day; once this many owners
308	     * have already been registered on a given business day no further owners may be created for
309	     * that day.
310	     */
311	    static final long DAILY_OWNER_LIMIT = 100;
312	
313	    @Override
314	    public boolean isRegistrationDateInFuture(LocalDate registrationDate) {
315	        return registrationDate != null && registrationDate.isAfter(LocalDate.now());
316	    }
317	
318	    @Override
319	    public LocalDate resolveRegistrationDate(LocalDate registrationDate) {
320	        LocalDate effectiveDate = registrationDate == null ? LocalDate.now() : registrationDate;
321	        return BusinessDay.rollForward(effectiveDate);
322	    }
323	
324	    @Override
325	    @Transactional(readOnly = true)
326	    public boolean isDailyOwnerLimitReached(LocalDate registrationDate) throws DataAccessException {
327	        return ownerRepository.countByRegistrationDate(registrationDate) >= DAILY_OWNER_LIMIT;
328	    }
329	
330	    /**
331	     * The number of owners that may be registered on a given day before further sign-ups for that
332	     * day are flagged with a bulk-signup warning. Once more than this many owners already exist for
333	     * the day, subsequent creates carry the warning.
334	     */
335	    static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
336	
337	    @Override
338	    @Transactional(readOnly = true)
339	    public boolean isBulkSignupWarranted(LocalDate registrationDate) throws DataAccessException {
340	        return ownerRepository.countByRegistrationDate(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
341	    }
342	
343	    @Override
344	    @Transactional(readOnly = true)
345	    public long countNamesakes(String firstName, String lastName) throws DataAccessException {
346	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
347	            .filter(owner -> owner.getFirstName().equalsIgnoreCase(firstName))
348	            .count();
349	    }
350	
351	    /**
352	     * Assign the owner's deterministic {@code householdId}, derived from its last name and postcode,
353	     * so owners sharing a last name and postcode share the id automatically. Owners without a
354	     * postcode belong to no household and are left without an id.
355	     *
356	     * @return the assigned household id, or {@code null} when the owner has no postcode
357	     */
358	    @Override
359	    @Transactional
360	    public String assignHousehold(Owner owner) throws DataAccessException {
361	        if (owner.getPostcode() == null) {
362	            return null;
363	        }
364	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
365	        owner.setHouseholdId(householdId);
366	        return householdId;
367	    }
368	
369	    /**
370	     * The number of members the owner's household will have once this (not yet persisted) owner is
371	     * created: the existing members sharing its household (last name and postcode), plus the owner
372	     * itself.
373	     */
374	    @Override
375	    @Transactional(readOnly = true)
376	    public long countHouseholdMembers(Owner owner) throws DataAccessException {
377	        return findHouseholdMembers(owner).size() + 1;
378	    }
379	
380	    /**
381	     * Resolve the membership level for a new owner, capping the level derived from its own membership
382	     * points so it never exceeds one above the current maximum level among its existing household
383	     * members. With no existing household member no cap applies and the derived level is returned.
384	     */
385	    @Override
386	    @Transactional(readOnly = true)
387	    public Integer resolveCappedMembershipLevel(Owner owner) throws DataAccessException {
388	        Integer derivedLevel = ownerMapper.deriveMembershipLevel(owner);
389	        return findHouseholdMembers(owner).stream()
390	            .map(ownerMapper::resolveMembershipLevel)
391	            .max(Integer::compareTo)
392	            .map(maxMemberLevel -> Math.min(derivedLevel, maxMemberLevel + 1))
393	            .orElse(derivedLevel);
394	    }
395	
396	    /**
397	     * Find the existing owners that share {@code owner}'s household, i.e. those with the same last
398	     * name (ignoring case) and the same postcode. An owner without a postcode belongs to no
399	     * household, so no members are returned for it. Soft-deleted owners are excluded, so they
400	     * neither block a create as a household duplicate nor count towards the household size.
401	     */
402	    private List<Owner> findHouseholdMembers(Owner owner) {
403	        if (owner.getPostcode() == null) {
404	            return List.of();
405	        }
406	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
407	            .filter(existing -> !existing.isDeleted())
408	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
409	            .toList();
410	    }
