424	    @Override
425	    @Transactional(readOnly = true)
426	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
427	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
428	    }
