430	    private <T> T findEntityById(Supplier<T> supplier) {
431	        try {
432	            return supplier.get();
433	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
434	            // Just ignore not found exceptions for Jdbc/Jpa realization
435	            return null;
436	        }
437	    }
