2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	/**
7	 * Decides whether an email address belongs to a disposable-email provider.
8	 *
9	 * <p>Disposable providers hand out throwaway inboxes, so owners registered with one cannot be
10	 * reliably contacted. An email is rejected when the domain after its {@code '@'} is on a small,
11	 * fixed blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). The
12	 * domain is compared case-insensitively; an absent email carries no domain and is accepted.
13	 */
14	public final class DisposableEmailRule {
15	
16	    /** Lower-cased domains whose emails are rejected as disposable. */
17	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
18	        "mailinator.com",
19	        "tempmail.com",
20	        "guerrillamail.com");
21	
22	    private DisposableEmailRule() {
23	    }
24	
25	    /**
26	     * Whether {@code email} uses a disposable-email domain.
27	     *
28	     * @param email the owner's email, possibly {@code null} or without an {@code '@'}
29	     * @return {@code true} when the domain following the last {@code '@'} is on the blocklist,
30	     *         {@code false} otherwise (including for a {@code null} email or one with no domain)
31	     */
32	    public static boolean isDisposable(String email) {
33	        if (email == null) {
34	            return false;
35	        }
36	        int at = email.lastIndexOf('@');
37	        if (at < 0) {
38	            return false;
39	        }
40	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
41	        return BLOCKED_DOMAINS.contains(domain);
42	    }
43	}
