60	    /**
61	     * Formats the owner's stored E.164 telephone for human display (country code, a space and the
62	     * national digits grouped in threes), leaving the raw {@code telephone} in E.164 form.
63	     */
64	    default String formatTelephoneDisplay(Owner owner) {
65	        return TelephoneFormatter.toDisplay(owner.getTelephone());
66	    }
67	
68	    /**
69	     * Formats the owner's initials as the upper-cased first letters of firstName and
70	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
71	     */
72	    default String formatInitials(Owner owner) {
73	        return initial(owner.getFirstName()) + initial(owner.getLastName());
74	    }
75	
76	    /** The upper-cased first letter of {@code name} followed by a dot. */
77	    private String initial(String name) {
78	        return Character.toUpperCase(name.charAt(0)) + ".";
79	    }
80	
81	    /**
82	     * Derives the owner's locality (canonical region) from the leading {@code <REGION>} segment of
83	     * its {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality always agrees with the
84	     * region encoded in the owner's identity.
85	     */
86	    default String resolveLocality(Owner owner) {
87	        String customerCode = owner.getCustomerCode();
88	        return customerCode.substring(0, customerCode.indexOf('-'));
89	    }
90	
91	    /**
92	     * Derives the owner's IANA timezone from its {@linkplain #resolveLocality(Owner) locality}
93	     * (canonical region) via the fixed region-to-timezone table, or {@code null} when the locality
94	     * has no known timezone.
95	     */
96	    default String resolveTimezone(Owner owner) {
97	        return TimezoneResolver.resolve(resolveLocality(owner));
98	    }
99	
100	    /**
101	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
102	     * last two digits of the {@linkplain Owner#getFiscalYear() fiscal year} of the registration
103	     * date, e.g. {@code "LON-SMI-0007-M26"}.
104	     */
105	    default String formatMembershipNumber(Owner owner) {
106	        return owner.getCustomerCode() + "-M" + owner.getFiscalYear().substring(2);
107	    }
108	
109	    /**
110	     * Computes the Luhn check digit over the decimal digits of the owner's customer code.
111	     */
112	    default Integer computeCheckDigit(Owner owner) {
113	        return Luhn.checkDigit(owner.getCustomerCode());
114	    }
115	
116	    /** The minimum tenure, in fiscal years, an owner must exceed to earn the tenure membership points. */
117	    int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
118	
119	    /** The minimum household size that earns the household membership points. */
120	    int HOUSEHOLD_POINTS_THRESHOLD = 3;
121	
122	    /**
123	     * Resolves the owner's membership points: starts at {@code 0}, plus {@code 2} when an email is
124	     * present, plus {@code 1} when the owner has no namesakes (namesakeCount is 0), plus {@code 2}
125	     * when the owner belongs to a household of {@value #HOUSEHOLD_POINTS_THRESHOLD} or more, plus
126	     * {@code 3} when the owner's tenure exceeds {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS} fiscal year.
127	     */
128	    default Integer resolveMembershipPoints(Owner owner) {
129	        int points = 0;
130	        if (hasEmail(owner)) {
131	            points += 2;
132	        }
133	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
134	            points += 1;
135	        }
136	        Integer householdSize = owner.getHouseholdSize();
137	        if (householdSize != null && householdSize >= HOUSEHOLD_POINTS_THRESHOLD) {
138	            points += 2;
139	        }
140	        if (owner.getTenureFiscalYears() > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
141	            points += 3;
142	        }
143	        return points;
144	    }
145	
146	    /**
147	     * Resolves the owner's effective membership level: the level persisted (capped) on creation when
148	     * present, otherwise the level {@linkplain #deriveMembershipLevel derived} from its membership
149	     * points.
150	     */
151	    default Integer resolveMembershipLevel(Owner owner) {
152	        Integer stored = owner.getMembershipLevel();
153	        return stored != null ? stored : deriveMembershipLevel(owner);
154	    }
155	
156	    /**
157	     * Derives the owner's numeric membership level from its {@linkplain #resolveMembershipPoints
158	     * membership points}: level {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
159	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more.
160	     */
161	    default Integer deriveMembershipLevel(Owner owner) {
162	        int points = resolveMembershipPoints(owner);
163	        if (points <= 1) {
164	            return 1;
165	        }
166	        if (points <= 3) {
167	            return 2;
168	        }
169	        if (points <= 5) {
170	            return 3;
171	        }
172	        return 4;
173	    }
174	
175	    /**
176	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
177	     * present, otherwise {@code "PHONE"}.
178	     */
179	    default String resolveContactPreference(Owner owner) {
180	        return hasEmail(owner) ? "EMAIL" : "PHONE";
181	    }
182	
183	    /** Whether the owner has a non-blank email address. */
184	    private boolean hasEmail(Owner owner) {
185	        return owner.getEmail() != null && !owner.getEmail().isBlank();
186	    }
187	
188	    /**
189	     * Resolves the owner's age band (as a string) from its birth date against its registration
190	     * date, or {@code null} when the owner has no birth date.
191	     */
192	    default String resolveAgeBand(Owner owner) {
193	        return owner.getAgeBand() == null ? null : owner.getAgeBand().name();
194	    }
195	
196	    @Mapping(target = "id", ignore = true)
197	    @Mapping(target = "pets", ignore = true)
198	    @Mapping(target = "householdId", ignore = true)
199	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
200	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
201	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
202	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
203	    Owner toOwner(OwnerFieldsDto ownerDto);
204	
205	    /**
206	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
207	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
208	     */
209	    @Named("normalizeAddress")
210	    default String normalizeAddress(String address) {
211	        return AddressNormalizer.normalize(address);
212	    }
213	
214	    /**
215	     * Compose the owner's canonical {@code address} from the supplied fields, preferring the
216	     * structured form: when {@code addressLine1} is present it is the normalized {@code addressLine1}
217	     * with a single space and the normalized {@code addressLine2} appended when that line is present;
218	     * otherwise it falls back to the normalized flat {@code address}. Composing into the single
219	     * {@code address} field keeps everything that reads the address (household hash, postcode
220	     * validation, locality) consistent whichever form was supplied.
221	     */
222	    default String composeAddress(OwnerFieldsDto ownerDto) {
223	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
224	        if (line1 == null || line1.isBlank()) {
225	            return normalizeAddress(ownerDto.getAddress());
226	        }
227	        String line2 = normalizeAddress(ownerDto.getAddressLine2());
228	        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
229	    }
230	
231	    /**
232	     * Store the telephone in E.164 form. Validation ({@code @Telephone}) has already guaranteed
233	     * the raw value normalizes to a valid E.164 number.
234	     */
235	    @Named("normalizeTelephone")
236	    default String normalizeTelephone(String telephone) {
237	        return TelephoneNormalizer.toE164(telephone);
238	    }
239	
240	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
241	
242	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
243	
244	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
245	        OwnerPageDto ownerPageDto = new OwnerPageDto();
246	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
247	        ownerPageDto.setPage(ownerPage.getNumber());
248	        ownerPageDto.setSize(ownerPage.getSize());
249	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
250	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
251	        return ownerPageDto;
252	    }
