153	    @Override
154	    @Transactional
155	    public void deleteOwner(Owner owner) throws DataAccessException {
156	        // Soft-delete: retain the record and flag it so it is excluded from duplicate/identity
157	        // checks, while remaining readable via findOwnerById.
158	        owner.setDeleted(true);
