35	/**
36	 * JPA implementation of the {@link OwnerRepository} interface.
37	 *
38	 * @author Mike Keith
39	 * @author Rod Johnson
40	 * @author Sam Brannen
41	 * @author Michael Isvy
42	 * @author Vitaliy Fedoriv
43	 */
44	@Repository
45	@Profile("jpa")
46	public class JpaOwnerRepositoryImpl implements OwnerRepository {
47	
48	    @PersistenceContext
49	    private EntityManager em;
50	
51	
52	    /**
53	     * Important: in the current version of this method, we load Owners with all their Pets and Visits while
54	     * we do not need Visits at all and we only need one property from the Pet objects (the 'name' property).
55	     * There are some ways to improve it such as:
56	     * - creating a Ligtweight class (example here: https://community.jboss.org/wiki/LightweightClass)
57	     * - Turning on lazy-loading and using open session in view pattern
58	     */
59	    @SuppressWarnings("unchecked")
60	    public Collection<Owner> findByLastName(String lastName) {
61	        // using 'join fetch' because a single query should load both owners and pets
62	        // using 'left join fetch' because it might happen that an owner does not have pets yet
63	        Query query = this.em.createQuery("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName");
64	        query.setParameter("lastName", lastName + "%");
65	        return query.getResultList();
66	    }
67	
68	    @Override
69	    @SuppressWarnings("unchecked")
70	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
71	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.lastName LIKE :lastName ORDER BY owner.id");
72	        query.setParameter("lastName", lastName + "%");
73	        query.setFirstResult((int) pageable.getOffset());
74	        query.setMaxResults(pageable.getPageSize());
75	        List<Owner> owners = query.getResultList();
76	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE :lastName");
77	        countQuery.setParameter("lastName", lastName + "%");
78	        long total = (long) countQuery.getSingleResult();
79	        return new PageImpl<>(owners, pageable, total);
80	    }
81	
82	    @Override
83	    @SuppressWarnings("unchecked")
84	    public Collection<Owner> findByLastNameIgnoreCase(String lastName) throws DataAccessException {
85	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE LOWER(owner.lastName) = LOWER(:lastName)");
86	        query.setParameter("lastName", lastName);
87	        return query.getResultList();
88	    }
89	
90	    @Override
91	    public Owner findById(int id) {
92	        // using 'join fetch' because a single query should load both owners and pets
93	        // using 'left join fetch' because it might happen that an owner does not have pets yet
94	        Query query = this.em.createQuery("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id");
95	        query.setParameter("id", id);
96	        return (Owner) query.getSingleResult();
97	    }
98	
99	
100	    @Override
101	    @SuppressWarnings("unchecked")
102	    public Collection<Owner> findByTelephone(String telephone) throws DataAccessException {
103	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.telephone = :telephone");
104	        query.setParameter("telephone", telephone);
105	        return query.getResultList();
106	    }
107	
108	    @Override
109	    public boolean existsByCustomerCode(String customerCode) throws DataAccessException {
110	        Query query = this.em.createQuery(
111	            "SELECT COUNT(owner) FROM Owner owner WHERE owner.customerCode = :customerCode");
112	        query.setParameter("customerCode", customerCode);
113	        return (long) query.getSingleResult() > 0;
114	    }
115	
116	    @Override
117	    public long count() throws DataAccessException {
118	        return (long) this.em.createQuery("SELECT COUNT(owner) FROM Owner owner").getSingleResult();
119	    }
120	
121	    @Override
122	    public long countByCityIgnoreCase(String city) throws DataAccessException {
123	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE LOWER(owner.city) = LOWER(:city)");
124	        query.setParameter("city", city);
125	        return (long) query.getSingleResult();
126	    }
127	
128	    @Override
129	    public long countByRegistrationDate(java.time.LocalDate registrationDate) throws DataAccessException {
130	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate");
131	        query.setParameter("registrationDate", registrationDate);
132	        return (long) query.getSingleResult();
133	    }
134	
135	    @Override
136	    public void save(Owner owner) {
137	        if (owner.getId() == null) {
138	            this.em.persist(owner);
139	        } else {
140	            this.em.merge(owner);
141	        }
142	
143	    }
144	
145		@SuppressWarnings("unchecked")
146		@Override
147		public Collection<Owner> findAll() throws DataAccessException {
148			Query query = this.em.createQuery("SELECT owner FROM Owner owner");
149	        return query.getResultList();
150		}
151	
152	    @SuppressWarnings("unchecked")
153	    @Override
154	    public Page<Owner> findAll(@NonNull Pageable pageable) throws DataAccessException {
155	        Query query = this.em.createQuery("SELECT owner FROM Owner owner ORDER BY owner.id");
156	        query.setFirstResult((int) pageable.getOffset());
157	        query.setMaxResults(pageable.getPageSize());
158	        List<Owner> owners = query.getResultList();
159	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
160	        long total = (long) countQuery.getSingleResult();
161	        return new PageImpl<>(owners, pageable, total);
162	    }
163	
164		@Override
165		public void delete(Owner owner) throws DataAccessException {
166			this.em.remove(this.em.contains(owner) ? owner : this.em.merge(owner));
167		}
168	
169	}
