283		public void delete(Owner owner) throws DataAccessException {
284			Map<String, Object> ownerParams = new HashMap<>();
285			ownerParams.put("id", owner.getId());
286	        List<Pet> pets = owner.getPets();
287	        // cascade delete pets
288	        for (Pet pet : pets){
289	        	Map<String, Object> petParams = new HashMap<>();
290	        	petParams.put("id", pet.getId());
291	        	// cascade delete visits
292	        	List<Visit> visits = pet.getVisits();
293	            for (Visit visit : visits){
294	            	Map<String, Object> visitParams = new HashMap<>();
295	            	visitParams.put("id", visit.getId());
296	            	this.namedParameterJdbcTemplate.update("DELETE FROM visits WHERE id=:id", visitParams);
297	            }
298	            this.namedParameterJdbcTemplate.update("DELETE FROM pets WHERE id=:id", petParams);
299	        }
300	        this.namedParameterJdbcTemplate.update("DELETE FROM owners WHERE id=:id", ownerParams);
301		}
